    /// <summary>
    /// MPJ_4054_CustomerAgingReport
    /// </summary>
    /// <param name = "_contract">
    /// get the CustAgingReportContract 
    /// </param>
    /// <returns>
    /// return report name 
    /// </returns>
    protected str getReportName(CustAgingReportContract _contract)
    {
        str reportNameLocal = next getReportName(_contract) ;

        if (_contract.parmDetailed())
        {
            if (_contract.parmIncludeAmountCur())
            {
                reportNameLocal = ssrsReportStr(METCustAgingReport, DesignWithDetailAndWithTransactionCur);
            }
            else
            {
                reportNameLocal = ssrsReportStr(METCustAgingReport, DesignWithDetailAndNoTransactionCur);
            }
        }
        else
        {
            if (_contract.parmIncludeAmountCur())
            {
                reportNameLocal = ssrsReportStr(METCustAgingReport, DesignWithNoDetailAndWithTransactionCur);
            }
            else
            {
                reportNameLocal = ssrsReportStr(METCustAgingReport, DesignWithNoDetailAndNoTransactionCur);
            }
        }
        return reportNameLocal;
    }
